const ruTranslate = (value) => {
  let out = clean(value);
  for (const [from, to] of translationPairs.sort((a, b) => b[0].length - a[0].length)) {
    const escaped = from.replace(/[.*+?^${}()|[\]\\]/gu, '\\$&');
    const pattern = /^\p{L}+[\p{L}-]*$/u.test(from) ? `(?<!\\p{L})${escaped}(?!\\p{L})` : escaped;
    out = out.replace(new RegExp(pattern, 'giu'), to);
  }
  for (const [from, to] of [
    ['під', 'под'], ['від', 'от'], ['вікном', 'окном'], ['ковдр', 'одеял'], ['одягу', 'одежды'], ['одягни', 'одежды'], ['зап’ястку', 'запястье'], ["зап'ястку", 'запястье'], ["зап'ястний", 'запястный'],
    ['манжети', 'манжеты'], ["пам’яті", 'памяти'], ["пам'яті", 'памяти'], ['акумуляторі', 'аккумуляторе'], ['бездротової', 'беспроводной'], ['клейкій', 'клеевой'], ['підставкою', 'подставкой'],
    ['пральну машинку', 'стиральную машину'], ['під мармур', 'под мрамор'], ['посудомийній', 'посудомоечной'], ['присосці', 'присоске'], ['високої', 'высокой'], ['вбирає', 'впитывающий'],
    ['що', 'который'], ['мильниці', 'мыльницы'], ['клейкій', 'клеевой'], ['клейова', 'клеевая'], ['унітаза', 'унитаза'], ['унітаз', 'унитаз'], ['зубної', 'зубной'], ['зубних', 'зубных'],
    ['пасти', 'пасты'], ['мило-піни', 'мыла-пены'], ['дезінфекціями', 'дезинфекцией'], ['турманіловою', 'турмалиновой'], ['під ліжко', 'под кровать'], ['під ліжком', 'под кроватью'],
  ]) out = out.replace(new RegExp(from.replace(/[.*+?^${}()|[\]\\]/gu, '\\$&'), 'giu'), to);
  return out.replace(/вікном/giu, 'окном').replace(/ковдр/giu, 'одеял').replace(/одягни/giu, 'одежды').replace(/одягу/giu, 'одежды')
    .replace(/під/giu, 'под').replace(/від/giu, 'от').replace(/акумуляторі/giu, 'аккумуляторе').replace(/бездротової/giu, 'беспроводной')
    .replace(/клейкій/giu, 'клеевой').replace(/підставкою/giu, 'подставкой').replace(/пральну машинку/giu, 'стиральную машину')
    .replace(/під мармур/giu, 'под мрамор').replace(/від шерсти/giu, 'от шерсти').replace(/від засоров/giu, 'от засоров').replace(/присосці/giu, 'присоске')
    .replace(/посудомийній/giu, 'посудомоечной').replace(/води/giu, 'воды').replace(/відгуку/giu, 'отклика').replace(/високої/giu, 'высокой')
    .replace(/зап['’]ястку/giu, 'запястье').replace(/зап['’]ястний/giu, 'запястный').replace(/манжети/giu, 'манжеты').replace(/пам['’]яті/giu, 'памяти')
    .replace(/Производытель/giu, 'Производитель').replace(/елементів Питание/giu, 'элементов питания').replace(/\s+Для\b/gu, ' для')
    .replace(/преміум[’']?якості/giu, 'высокого качества').replace(/турманіловою/giu, 'турмалиновой').replace(/дезінфекціями/giu, 'дезинфекцией')
    .replace(/\s{2,}/gu, ' ').replace(/\s+([,.;:])/gu, '$1').trim();
};

const fixUa = (v) => firstUpper(clean(v)
  .replace(/\bОрганізатор\b/giu, 'Органайзер')
  .replace(/Глибина\s+корзини|Глубина\s+корзины/giu, 'Глибина кошика')
  .replace(/\bВместимость\b/giu, 'Місткість')
  .replace(/\bКорзина\b/giu, 'Кошик')
  .replace(/\bсудочки\b/giu, 'судочки')
  .replace(/\bмиючий\b/giu, 'мийний')
  .replace(/\bавтоматизований дозатор\b/giu, 'автоматичний дозатор')
  .replace(/\bодягни\b/giu, 'одягу')
  .replace(/\bдезінфекціями\b/giu, 'дезінфекцією')
  .replace(/\bтурманіловою\b/giu, 'турмаліновою')
  .replace(/\bпреміум'якості\b/giu, 'високої якості')
  .replace(/преміум[’']?якості/giu, 'високої якості'));
const stripTokens = (v) => clean(v)
  .replace(/(?<!\p{L})(?:BOWL LIGHT|AND|XL|LY|MAC|MAG|MC|RD|DM|ER|GM|EN|PS|HTC|APP|FS|UKC|NEW|PREMIUM|SUPRETTO|EXTERNAL|SHOWER|RECOLOR|WIPE|СОНЯЧНА|КОРІВКА|РОЗПРОДАЖ)(?!\p{L})[-_ ]*\w*/giu, '')
  .replace(/(?<!\p{L})[A-Z]{1,5}[-_]\d{1,6}(?!\p{L})/gu, '')
  .replace(/(?<![\p{L}\p{N}])\d{3,}[A-Za-z]?(?![\p{L}\p{N}])/gu, '')
  .replace(/(?<![\p{L}\p{N}])\d{3,}(?![\p{L}\p{N}])/gu, '')
  .replace(/(?<!\p{L})[A-Za-z][A-Za-z0-9-]*(?!\p{L})/gu, '')
  .replace(/(?<!\p{L})(?:-\d{1,3}){1,3}(?!\p{L})/gu, '')
  .replace(/\s*°/gu, '')
  .replace(/\(\s*\)/gu, '')
  .replace(/\s{2,}/gu, ' ').replace(/\s+([,.;:])/gu, '$1').replace(/[,;:–—-]+$/gu, '').trim();

const source = JSON.parse(await fs.readFile(sourcePath, 'utf8')).products;
const sourceBySku = new Map(source.map((p) => [clean(p.sku), p]));
const wb = await SpreadsheetFile.importXlsx(await FileBlob.load(inputPath));
const products = wb.worksheets.getItem('Export Products Sheet');
const used = products.getUsedRange();
const headers = used.values[0];
const ix = Object.fromEntries(headers.map((h, i) => [h, i]));
for (const h of ['Код_товару', 'Назва_позиції', 'Назва_позиції_укр', 'Опис', 'Опис_укр', 'Пошукові_запити', 'Пошукові_запити_укр', 'Унікальний_ідентифікатор', 'Ідентифікатор_товару']) {
  if (ix[h] === undefined) throw new Error(`Missing product field: ${h}`);
}
const nameSlots = headers.map((h, i) => h === 'Назва_Характеристики' ? i : -1).filter((i) => i >= 0);
const unitSlots = headers.map((h, i) => h === 'Одиниця_виміру_Характеристики' ? i : -1).filter((i) => i >= 0);
const valueSlots = headers.map((h, i) => h === 'Значення_Характеристики' ? i : -1).filter((i) => i >= 0);
if (nameSlots.length < 3 || nameSlots.length !== unitSlots.length || nameSlots.length !== valueSlots.length) throw new Error('Characteristic columns are not a complete repeated triplet');

const contextFor = (p) => {
  const t = `${p.title} ${(p.attributes ?? []).map((a) => `${a.name} ${a.value}`).join(' ')}`.toLocaleLowerCase('uk-UA');
  if (/сигналіза|сигнализац/iu.test(t)) return { ua: 'контролю безпеки будинку або квартири', ru: 'контроля безопасности дома или квартиры' };
  if (/очисник скла|очиститель стекла|миття вікон|для вікон|автомобільного скла/iu.test(t)) return { ua: 'очищення скла, вікон і дзеркал', ru: 'очистки стекла, окон и зеркал' };
  if (/термометр|тонометр|пульс|пірометр/iu.test(t)) return { ua: 'домашнього використання', ru: 'домашнего использования' };
  if (/кухн|посуд|яєц|аерофрит|маслян|відкривач|судоч|помпа для води/iu.test(t)) return { ua: 'кухні', ru: 'кухни' };
  if (/під ліж|одяг|білизн|взут|пральн|контейнер-сітка/iu.test(t)) return { ua: 'дому та зберігання речей', ru: 'дома и хранения вещей' };
  if (/ванн|душ|унітаз|йорж|мочалк|кран|змішувач|аератор/iu.test(t)) return { ua: 'ванної кімнати', ru: 'ванной комнаты' };
  if (/одяг|білизн|взут|органайз|зберіган|вішал|кошик|чохол|пральн/iu.test(t)) return { ua: 'дому та зберігання речей', ru: 'дома и хранения вещей' };
  if (/електрич|сигналіза|гучномов|насос|заряд|живлен/iu.test(t)) return { ua: 'щоденного використання', ru: 'ежедневного использования' };
  return { ua: 'дому', ru: 'дома' };
};

const charNameFix = (v) => firstUpper(clean(v).replace(/\bОб[`’']єм\b/gu, 'Об’єм').replace(/\bмодель\b/giu, ''));
const extractDescriptionChars = (description) => {
  const text = clean(description);
  const marker = text.match(/(?:Характеристики|Технічні характеристики)\s*:/iu);
  if (!marker) return [];
  const tail = text.slice((marker.index ?? 0) + marker[0].length);
  const labels = '(?:Призначення|Об[`’\']?єм|Місткість|Конструкція|Особливості|Тип застібки|Матеріал(?: корпусу| насадки)?|Розміщення|Форма|Розмір(?:и)?|Габарити|Кількість(?: гачків| ярусів)?|Живлення|Час заряджання|Час стерилізації|Метод зарядки|Монтаж|Сумісність|Датчик руху|Варіанти кольорів|LED лампочка|Країна виробник|Колір|Тип|Основне призначення|Похибка|Вага|Потужність)';
  const pieces = tail.split(new RegExp(`(?=\\s+${labels}\\s*[:—-])`, 'iu')).flatMap((part) => part.split(/[;\n]+/u));
  const out = [];
  for (const piece of pieces) {
    const match = clean(piece).match(new RegExp(`^(${labels})\\s*[:—-]\\s*(.+)$`, 'iu'));
    if (!match) continue;
    const name = charNameFix(match[1]);
    const value = clean(match[2]).replace(/[.;]+$/gu, '');
    if (!name || !value || value.length > 120 || /(?:модель|артикул|sku|код)/iu.test(`${name} ${value}`)) continue;
    if (out.some((x) => norm(x.name) === norm(name) && norm(x.value) === norm(value))) continue;
    out.push({ name, value });
  }
  return out;
};

const collectChars = (p) => {
  const out = [];
  const add = (name, value) => {
    const n = charNameFix(fixUa(name)); const v = clean(value).replace(/[.;]+$/gu, '');
    if (!n || !v || n.length > 60 || v.length > 120) return;
    if (/(?:модель|артикул|sku|код)/iu.test(`${n} ${v}`)) return;
    if (out.some((x) => norm(x.name) === norm(n) && norm(x.value) === norm(v))) return;
    out.push({ name: n, value: v });
  };
  for (const a of p.attributes ?? []) add(a.name, a.value);
  // Use only structured supplier attributes. Long supplier descriptions can
  // contain copied text from adjacent products and must not leak into the
  // title, benefits or Prom characteristics of this product.
  if (!out.some((x) => /виробник|производитель/iu.test(x.name))) add('Виробник', 'AND');
  return out.slice(0, nameSlots.length);
};

const titleWithFeatures = (baseUa, baseRu, p, chars) => {
  const t = `${p.title} ${(p.attributes ?? []).map((a) => `${a.name} ${a.value}`).join(' ')}`.toLocaleLowerCase('uk-UA');
  const additions = [];
  const add = (ua, ru) => {
    if (!additions.some((x) => x.ua === ua)) additions.push({ ua, ru });
  };
  if (/датчик руху|сенсор/iu.test(t)) add('з датчиком руху', 'с датчиком движения');
  if (/безконтактн/iu.test(t)) add('безконтактний', 'бесконтактный');
  if (/телескопічн/iu.test(t)) add('з телескопічною ручкою', 'с телескопической ручкой');
  if (/самоклейн|клейка основа/iu.test(t)) add('самоклейний', 'самоклеящийся');
  if (/акумулятор/iu.test(t) && !/акумуляторн/iu.test(baseUa)) add('акумуляторний', 'аккумуляторный');
  if (/2 ярус|два ярус/iu.test(t)) add('2-ярусний', '2-ярусный');
  const volume = chars.find((a) => /об[`’']?єм|місткість/iu.test(a.name) && /\d/gu.test(a.value));
  if (volume && /органайз|контейнер|кошик/iu.test(baseUa) && !/\d\s*(?:л|шт)/iu.test(baseUa)) add(volume.value, ruTranslate(volume.value));
  let ua = fixUa(stripTokens(baseUa)); let ru = clean(stripTokens(baseRu));
  for (const x of additions) {
    if (ua.length + x.ua.length + 1 <= 130 && !norm(ua).includes(norm(x.ua))) ua = `${ua} ${x.ua}`;
    if (ru.length + x.ru.length + 1 <= 110 && !norm(ru).includes(norm(x.ru))) ru = `${ru} ${x.ru}`;
  }
  return { ua: ua.replace(/\s{2,}/gu, ' ').trim(), ru: ru.replace(/\s{2,}/gu, ' ').trim() };
};

const ruTitleFromUa = (value) => {
  let out = ruTranslate(fixUa(stripTokens(value)));
  out = out.replace(/\bис\b/giu, 'из').replace(/\bис\s+/giu, 'из ')
    .replace(/\bExternal Shower\b/giu, '').replace(/\bSupretto\b/giu, '')
    .replace(/\bдля\s+унітаза\b/giu, 'для унитаза')
    .replace(/который\s+впитывающий/giu, 'впитывающий')
    .replace(/\b(зубная\s+щетка|электрическая\s+зубная\s+щетка|аккумуляторная\s+зубная\s+щетка)\s+аккумуляторный\b/giu, '$1 аккумуляторная')
    .replace(/\bс\s+поворотом\s+°/giu, 'с поворотом')
    .replace(/\bдозатор\s+Для\b/gu, 'дозатор для')
    .replace(/\bАвтоматичная\b/giu, 'Автоматическая')
    .replace(/\s{2,}/gu, ' ').replace(/\s+([,.;:])/gu, '$1').trim();
  return firstUpper(out);
};

